# ------------------------------------------------------------------ 3 may review and conjugation
_TF = [("May maraming bisita rito.", "False. Delete maraming or may (May bisita rito / Maraming bisita rito).", "False"), ("May cannot be conjugated.", "True.", "True"), ("The word maraming makes a sentence negative.", "False. Walang makes it negative.", "False"), ("May is the translation of the word “to be.”", "False. May is not the translation of “to be.”", "False"), ("With may or me we can use linkers.", "False. Linkers are not used with may/me.", "False"), ("With mayroon you need a linker.", "True.", "True"), ("With may you need a main verb.", "False. A main verb is not needed.", "False")]
_TR = [("May kasalan sa simbahan ng Santo Domingo.", "There is a wedding at Santo Domingo Church. (also Mayroong kasalan sa simbahan ng Santo Domingo.)"), ("May limang pares ng ninong at ninang.", "There are five pairs of sponsors. (also Mayroong limang pares ng ninong at ninang.)"), ("May magandang babaeng ikakasal sa labas ng simbahan.", "There is a beautiful bride waiting outside the church. (also Mayroong magandang babaeng ikakasal sa labas ng simbahan.)"), ("May pareng naghihintay sa loob ng simbahan.", "There is a priest waiting inside the church. (also Mayroong pareng naghihintay sa loob ng simbahan.)"), ("May puting kotse sa harap ng simbahan.", "There is a white car in front of the church. (also Mayroong puting kotse sa harap ng simbahan.)"), ("Walang mga bulaklak sa loob ng simbahan.", "There are no flowers in the church.")]
_CS = [("Meron akong kilalang modista at parentahan.", "I know a dressmaker and a rental place. (literally: I have knowledge of a dressmaker and a rental place.)"), ("May kakilala rin akong caterer.", "I also know a caterer."), ("Kung hindi pa, meron akong irerekomenda.", "If not yet, I can recommend someone."), ("Sabihin mo lang anak, kung ano pang wala o kulang.", "Just tell me, child, what else you lack or don’t have."), ("Huwag isukat ang trahe de boda at may masamang mangyayari.", "Don’t try on the wedding dress because something bad might happen."), ("Walang mawawala kung susundin ang pamahiin.", "Nothing will be lost if the superstitious practices are followed.")]
_NEG = [("May natanggap kaming imbitasyon sa kasal nina Jose at Josefa.", "Wala kaming natanggap na imbitasyon sa kasal nina Jose at Josefa."), ("Mayroon kaming litrato at video ng kasalan nila.", "Wala kaming litrato at video ng kasalan nila."), ("May malaking regalo kami para sa bagong kasal.", "Wala kaming malaking regalo para sa bagong kasal."), ("Mayroon silang isang linggong pulotgata sa Boracay.", "Wala silang isang linggong pulotgata sa Boracay."), ("May malaking handaan sa Manila Hotel ngayon.", "Walang malaking handaan sa Manila Hotel ngayon."), ("Mayroon ba kayong pupuntahang kasalan mamayang gabi?", "Wala ba kayong pupuntahang kasalan mamayang gabi?")]
_NEGE = ["We received an invitation to Jose and Josefa’s wedding. → We did not receive an invitation.", "We have a photo and video of their wedding. → We don’t have a photo and video.", "We have a big gift for the newlyweds. → We don’t have a big gift.", "They have a one-week honeymoon in Boracay. → They don’t have a one-week honeymoon.", "There is a big reception at the Manila Hotel today. → There is no big reception today.", "Do you have a wedding to go to tonight? → Don’t you have a wedding to go to tonight?"]
_RW = [("May pera ba kayo para sa kasal ninyo?", "Meron ka bang pera para sa kasal ninyo?"), ("May kakilala ba kayong mananahi ng trahe de boda?", "Meron ba kayong kakilalang mananahi ng trahe de boda?"), ("Mayroon ka bang kakilalang caterer?", "May kakilala ka bang caterer?"), ("Mayroon na bang balita sa handaan sa kasal ni Jack?", "May balita na ba sa handaan sa kasal ni Jack?"), ("May pamahiin ka bang alam tungkol sa pag-aasawa?", "Meron ka bang alam na pamahiin tungkol sa pag-aasawa?")]
_CV = [("magtipid", "to save, conserve", *mag_forms("tipid")[0:4]), ("maghanda", "to get ready", *mag_forms("handa")[0:4]), ("maghanap", "to look for", *mag_forms("hanap")[0:4]), ("tumawag", "to call", *um_forms("tawag")[0:4]), ("humingi", "to ask", *um_forms("hingi")[0:4])]
_CVR = [(inf, e, p, pr, f) for inf, e, i0, p, pr, f in [(a, b, c, d, e2, f2) for (a, b, c, d, e2, f2) in _CV]]
